export function checkNearbyLocation(heroX, heroY) {
  for (const loc of OFFICIAL_LOCATIONS) {
    const z = loc.interactionZone;
    if (heroX >= z.minX && heroX <= z.maxX && heroY >= z.minY && heroY <= z.maxY) {
      return loc;
    }
  }
  return null;
}

